package cc.crafto.ui;
import com.google.gson.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static cc.crafto.ui.Protocol.*;
class MenuReflowTest {
    JsonObject menu(){var children=new JsonArray();for(int i=0;i<9;i++)children.add(object("id","b"+i,"type","button","action","handler-"+i));return object("id","example","responsive",true,"width",620,"height",350,"components",List.of(object("id","heading","type","text","layoutRole","description","x",16,"y",56,"w",588,"h",16),object("id","main","type","grid","layoutRole","content","x",16,"y",80,"w",588,"h",220,"columns",3,"rowHeight",46,"gap",8,"children",children)));}
    @Test void narrowMenusReflowRatherThanShrinkText(){var source=menu();var original=source.deepCopy();var narrow=MenuReflow.fit(source,304);var grid=narrow.getAsJsonArray("components").get(1).getAsJsonObject();assertEquals(2,integer(grid,"columns",0));assertTrue(integer(narrow,"height",0)>350);assertEquals(original,source);assertEquals(46,integer(grid,"rowHeight",0));}
    @Test void everyActionSurvivesAndCellsStayInsideTheWindow(){for(int w:new int[]{240,280,304,480,620}){var m=MenuReflow.fit(menu(),w);var grid=m.getAsJsonArray("components").get(1).getAsJsonObject();assertEquals(9,grid.getAsJsonArray("children").size());int right=integer(grid,"x",0)+integer(grid,"w",0);assertTrue(right<=w-16);var ids=new HashSet<String>();for(var n:grid.getAsJsonArray("children")){assertTrue(ids.add(str(n.getAsJsonObject(),"id","")));assertFalse(str(n.getAsJsonObject(),"action","").isEmpty());}}}
    @Test void unmarkedApiLayoutsRemainUnmodified(){var m=menu();m.remove("responsive");assertEquals(m,MenuReflow.fit(m,240));}
    @Test void decorativeAsideCollapsesButContentAndActionsRemain(){var m=menu();var nodes=m.getAsJsonArray("components");nodes.add(object("id","aside","type","panel","layoutRole","aside","w",152,"h",228,"children",List.of(object("id","avatar","type","avatar"),object("id","name","type","text","text","${player.name}"),object("id","status","type","text","text","${player.status}"))));nodes.add(object("id","refresh","type","button","layoutRole","actions","action","refresh"));var n=MenuReflow.fit(m,304);var aside=n.getAsJsonArray("components").get(2).getAsJsonObject();assertEquals(1,aside.getAsJsonArray("children").size());assertTrue(aside.toString().contains("${player.name} · ${player.status}"));assertEquals("refresh",n.getAsJsonArray("components").get(3).getAsJsonObject().get("action").getAsString());}
    @Test void shortViewportPrioritizesActionsOverTheDecorativeAvatar(){var m=menu();m.getAsJsonArray("components").add(object("id","aside","type","panel","layoutRole","aside","w",152,"h",228,"children",new JsonArray()));var n=MenuReflow.fit(m,304,164);assertEquals(0,n.getAsJsonArray("components").get(2).getAsJsonObject().get("h").getAsInt());assertEquals(80,n.getAsJsonArray("components").get(1).getAsJsonObject().get("y").getAsInt());assertEquals(9,n.getAsJsonArray("components").get(1).getAsJsonObject().getAsJsonArray("children").size());}
    @Test void legacyNavigationIsDensifiedWithoutLosingAnyAction(){var m=menu();m.addProperty("id","society");m.remove("responsive");var grid=m.getAsJsonArray("components").get(1).getAsJsonObject();grid.addProperty("id","modules");grid.remove("layoutRole");grid.addProperty("rowHeight",72);var n=MenuReflow.fit(m,620,400);var compact=n.getAsJsonArray("components").get(1).getAsJsonObject();assertTrue(integer(compact,"rowHeight",100)<=42);assertEquals(9,compact.getAsJsonArray("children").size());assertEquals(1,integer(n,"pageCount",0));assertTrue(integer(n,"height",999)<=400);assertEquals(72,integer(grid,"rowHeight",0));}
    @Test void tinyNavigationPagesInsteadOfCreatingAScrollTail(){var m=menu();m.addProperty("id","society");m.getAsJsonArray("components").get(1).getAsJsonObject().addProperty("id","modules");var n=MenuReflow.fit(m,304,164);assertTrue(integer(n,"pageCount",0)>1);assertTrue(integer(n,"height",999)<=164);var grid=n.getAsJsonArray("components").get(1).getAsJsonObject();int capacity=integer(grid,"pageCapacity",0);assertTrue(capacity>0);assertTrue(capacity<9);assertEquals(9,grid.getAsJsonArray("children").size());}
    @Test void builtinLookingIdsDoNotOverrideUnmarkedApiLayouts(){var m=menu();m.addProperty("id","main");m.remove("responsive");assertEquals(m,MenuReflow.fit(m,240,164));m.getAsJsonArray("components").get(1).getAsJsonObject().addProperty("id","modules");m.addProperty("responsive",false);assertEquals(m,MenuReflow.fit(m,240,164));}
}
